static void InitializeArmorMaps(){
    static bool once = true;
    if(!once) return;
    once = false;
    InitializeHelmetMap();
    InitializeChestplateMap();
    InitializeLeggingsMap();
    InitializeGauntletsMap();
    InitializeBootsMap();
}
static UIImage* GetArmorIcon(UObject* ArmorPointer){
    InitializeArmorMaps();
    if(!utils.isValidAdress(ArmorPointer)) return NullImage;
    
    EPrimalEquipmentType ArmorType = utils.Read<EPrimalEquipmentType>(ArmorPointer + 0x13a);
    string ArmorString = gameUtils.SGetObjectName(ArmorPointer);
    if(ArmorType == EquippedType_Helmet){
        if(HelmetSearchMap.find(ArmorString) != HelmetSearchMap.end()){
            EHelmetImageType ImageIndex = HelmetSearchMap[ArmorString];
            return HelmetArray[ImageIndex];
        }
    } else if(ArmorType == EquippedType_Chestplate){
        if(ChestplateSearchMap.find(ArmorString) != ChestplateSearchMap.end()){
            EChestplateImageType ImageIndex = ChestplateSearchMap[ArmorString];
            return ChestplateArray[ImageIndex];
        }
        
    } else if(ArmorType == EquippedType_Pants){
        if(LeggingsSearchMap.find(ArmorString) != LeggingsSearchMap.end()){
            ELeggingsImageType ImageIndex = LeggingsSearchMap[ArmorString];
            return LeggingsArray[ImageIndex];
        }
        
    } else if(ArmorType == EquippedType_Gloves){
        if(GauntletsSearchMap.find(ArmorString) != GauntletsSearchMap.end()){
            EGauntletsImageType ImageIndex = GauntletsSearchMap[ArmorString];
            return GauntletsArray[ImageIndex];
        }
        
    } else if(ArmorType == EquippedType_Boots){
        if(BootsSearchMap.find(ArmorString) != BootsSearchMap.end()){
            EBootsImageType ImageIndex = BootsSearchMap[ArmorString];
            return BootsArray[ImageIndex];
        }
    }
    return NullImage;
}
@implementation PlayerArmorIcon
- (void)InitializeImages {
    
    InitializeArmorMaps();
    self.userInteractionEnabled = NO;

    CTFontRef ref = CTFontCreateWithName((CFStringRef)@"Copperplate-Bold", 10, NULL);
    [CATransaction begin]; [CATransaction setDisableActions:YES]; [CATransaction commit];
    NSMutableDictionary *newActions = [[NSMutableDictionary alloc] initWithObjectsAndKeys:[NSNull null], @"position", [NSNull null], @"bounds", nil];
    
    self.DuraPercent = [CATextLayer layer];
    self.DuraPercent.string = @"Hi";
    self.DuraPercent.fontSize = 10;
    self.DuraPercent.wrapped = NO;
    self.DuraPercent.alignmentMode = kCAAlignmentCenter;
    self.DuraPercent.frame = CGRectMake(0,IconSize-10,IconSize,10);
    self.DuraPercent.contentsScale = [UIScreen mainScreen].scale;
    self.DuraPercent.shadowColor = [[UIColor darkGrayColor] CGColor];
    self.DuraPercent.shadowOffset = CGSizeMake(0.6, 0.6);
    self.DuraPercent.shadowOpacity = 0.9;
    self.DuraPercent.shadowRadius = 0;
    self.DuraPercent.font = ref;
    self.DuraPercent.actions = newActions;
    self.DuraPercent.foregroundColor = [UIColor whiteColor].CGColor;
    [self.layer addSublayer:self.DuraPercent];
}
- (void)move:(float)x y:(float)y{
    self.frame = CGRectMake(x, y, IconSize, IconSize);
}
- (void)SetDurability:(float)Percentage{
    if(ESPArmorIconDura)
        self.DuraPercent.string = [NSString stringWithFormat:@"%.0f", Percentage * 100];
    else
        self.DuraPercent.string = @" ";
}
@end



static UIImage* BuffsArray[5];
static std::map<string, int> BuffsMap;
static void InitializeBuffsMap()__attribute((__annotate__(("nostrenc"))));
static void InitializeBuffsMap(){
    static bool once = true;
    if(!once) return;
    once = false;
    
    BuffsMap["Buff_Hangover_C"] = 0;
    BuffsMap["Buff_Beer_C"] = 1;
    BuffsMap["Buff_Premium_ThickSkin_C"] = 2;
    BuffsMap["Buff_Premium_LegDay_C"] = 3;
    BuffsMap["Buff_Premium_Feast_C"] = 4;
    
    BuffsArray[0] = InitWithString(@"");
    BuffsArray[1] = InitWithString(@"");
    BuffsArray[2] = InitWithString(@"");
    BuffsArray[3] = InitWithString(@"");
    BuffsArray[4] = InitWithString(@"");
}
static bool isValidBuffImage(string BuffName){
    if(BuffsMap.find(BuffName) != BuffsMap.end()){
        return true;
    }
    return false;
}
static UIImage* GetBuffImage(string BuffName){
    if(BuffsMap.find(BuffName) != BuffsMap.end()){
        int ImageIndex = BuffsMap[BuffName];
        return BuffsArray[ImageIndex];
    }
    return NullImage;
}
static int GetBuffIndex(string BuffName){
    if(BuffsMap.find(BuffName) != BuffsMap.end()){
        int ImageIndex = BuffsMap[BuffName];
        return ImageIndex;
    }
    return 0;
}

@implementation BuffIcon
- (void)InitializeImages {
    InitializeBuffsMap();
    self.userInteractionEnabled = NO;
}
- (void)move:(float)x y:(float)y{
    self.frame = CGRectMake(x, y, IconSize, IconSize);
}
@end




