/*
 BRAINSTORM:
 
 Armor: Easy to Filter by Helmet/Chest/Leggs whatever
 
 
 Weapon Icons - Above Player Name size 30 x 20 no background
 Armor Icons - Below Health Bar, only do helmet/chest/leggings/gaunt/boots,
 
 In each armor icon have a dura percent over it (CATextLayer) and background is quality color
 each a square size 14x14 (health bar 70)
 
 DrawBottomMiddleScreenLocation is the Middle Bottom of the Health Bar
 
 
 
 under the armor
 
 
 EquippedType_Helmet = 0,
 EquippedType_Chestplate = 1,
 EquippedType_Pants = 2,
 EquippedType_Boots = 3,
 EquippedType_Gloves = 4,
 EPrimalItemStat
 */
static float (*GetItemStatInfo)(UObject* PrimalItem, EPrimalItemStat StatType) = (float(*)(UObject*, EPrimalItemStat))utils.getOffset(0x8c89d8);


static UIColor* QualityColors[ArmorQuality_Count] = {[UIColor grayColor], [UIColor greenColor], [UIColor blueColor], [UIColor purpleColor], [UIColor yellowColor], [UIColor cyanColor]};

void ArmorIcons::Reset(){
    for(int i = 0; i<5; ++i){
        ArmorButtons[i].frame = CGRectMake(-100, -100, IconSize, IconSize);
        ArmorButtons[i].backgroundColor = [UIColor clearColor];
        ArmorButtons[i].layer.cornerRadius = ArmorButtons[i].frame.size.width * 0.3f;
        
        BuffButtons[i].frame = CGRectMake(-100, -100, IconSize, IconSize);
        BuffButtons[i].backgroundColor = [UIColor clearColor];
        BuffButtons[i].layer.cornerRadius = BuffButtons[i].frame.size.width * 0.3f;
        
    }
    
    WeaponButton.frame = CGRectMake(-100, -100, IconSize * WeaponIconWidthMultiplier , IconSize * WeaponIconHeightMultiplier);
    WeaponButton.backgroundColor = [UIColor clearColor];
    
    /*
     BuffIcon* BuffButtons[5];
     WeaponIcon* WeaponButton;
     */
}
void ArmorIcons::Initialize(){
    InitializeNullImage();
    
    UIView* mainView = [UIApplication sharedApplication].windows[0].rootViewController.view;
    for(int i = 0; i<5; ++i){
        ArmorButtons[i] = [PlayerArmorIcon buttonWithType:UIButtonTypeRoundedRect];
        ArmorButtons[i].frame = CGRectMake(-100, -100, IconSize, IconSize);
        ArmorButtons[i].backgroundColor = [UIColor clearColor];
        [ArmorButtons[i] InitializeImages];
        [ArmorButtons[i] setBackgroundImage:NullImage forState:UIControlStateNormal];
        [hideRecordView addSubview:ArmorButtons[i]];
        
        BuffButtons[i] = [BuffIcon buttonWithType:UIButtonTypeRoundedRect];
        BuffButtons[i].frame = CGRectMake(-100, -100, IconSize, IconSize);
        BuffButtons[i].backgroundColor = [UIColor clearColor];
        [BuffButtons[i] InitializeImages];
        [BuffButtons[i] setBackgroundImage:NullImage forState:UIControlStateNormal];
        [hideRecordView addSubview:BuffButtons[i]];
    }
    
    WeaponButton = [WeaponIcon buttonWithType:UIButtonTypeRoundedRect];
    WeaponButton.frame = CGRectMake(-100, -100, IconSize * WeaponIconWidthMultiplier, IconSize * WeaponIconHeightMultiplier);
    WeaponButton.backgroundColor = [UIColor clearColor];
    [WeaponButton InitializeImages];
    [WeaponButton setBackgroundImage:NullImage forState:UIControlStateNormal];
    [hideRecordView addSubview:WeaponButton];
    
    /*
     BuffIcon* BuffButtons[5];
     WeaponIcon* WeaponButton;
     */
    
    
}
void ArmorIcons::DrawForPlayer(Vector2 ScreenLocation, UObject* Player){
    if(!utils.isValidAdress(Player)) return;
    
    bool HasArmor[5] = {false};
    EArmorQuality ArmorQualities[5] = {ArmorQuality_Primitive};
    float ArmorDurabilities[5] = {0};
    UObject* ValidArmorPieces[5];
    int NumArmorPieces = 0;
    UObject* PlayerInventory = utils.Read<UObject*>(Player + 0x1de8);
    TArray<UObject*> InventoryArmorArray =  utils.Read<TArray<UObject*>>(PlayerInventory + 0x238);
    
    if(InventoryArmorArray.IsValidArray() && ESPArmorIcons)
    {
        for(int i = 0; i<InventoryArmorArray.Count; ++i)
        {
            UObject* CurrentArmorPiece = InventoryArmorArray[i];
            if(utils.isValidAdress(CurrentArmorPiece))
            {
                EPrimalEquipmentType ArmorType = utils.Read<EPrimalEquipmentType>(CurrentArmorPiece + 0x13a);
                EArmorQuality ArmorQuality = utils.Read<EArmorQuality>(CurrentArmorPiece + 0x268);
                if(ArmorType < 5)
                {
                    HasArmor[ArmorType] = true;
                    ArmorQualities[ArmorType] = ArmorQuality;
                    ValidArmorPieces[ArmorType] = CurrentArmorPiece;
                
                    float CurrentDurability = utils.Read<float>(CurrentArmorPiece + 0x5b4);
                    float DurabilityPercentage = CurrentDurability/GetItemStatInfo(CurrentArmorPiece, ItemStat_MaxDurability);
                    ArmorDurabilities[ArmorType] = DurabilityPercentage;
                    
                    NumArmorPieces++;
                }
            }
        }
        
        float IconsWidth = IconSize * NumArmorPieces;
        Vector2 ArmorDrawStartLocation = Vector2(ScreenLocation.X - IconsWidth/2, ScreenLocation.Y + 1);
        
        if(NumArmorPieces > 0)
        {
            for(int i = 0; i<5; ++i)
            {
                if(HasArmor[i])
                {
                    ArmorButtons[i].backgroundColor = QualityColors[ArmorQualities[i]];
                    [ArmorButtons[i] move:ArmorDrawStartLocation.X y:ArmorDrawStartLocation.Y];
                    [ArmorButtons[i] SetDurability:ArmorDurabilities[i]];
                    ArmorDrawStartLocation.X += IconSize;
                    [ArmorButtons[i] setBackgroundImage:GetArmorIcon(ValidArmorPieces[i]) forState:UIControlStateNormal];
                }
            }
        }
    }
    
    if(ESPArmorIcons)
    {
        TArray<UObject*> PlayerBuffArray = utils.Read<TArray<UObject*>>(Player + 0xac0);
        if(PlayerBuffArray.IsValidArray())
        {
            int RelevantBuffCount = 0;
            bool ReleventBuffsFound[5] = {false};
            UObject* ReleventBuffPointers[5] = {nullptr};
            for(int i = 0; i<PlayerBuffArray.Count; i++)
            {
                UObject* CurrentBuff = PlayerBuffArray[i];
                if(utils.isValidAdress(CurrentBuff))
                {
                    string BuffName = gameUtils.SGetObjectName(CurrentBuff);
                    if(isValidBuffImage(BuffName))
                    {
                        RelevantBuffCount++;
                        int ReleventBuffIndex = GetBuffIndex(BuffName);
                        ReleventBuffsFound[ReleventBuffIndex] = true;
                        ReleventBuffPointers[ReleventBuffIndex] = CurrentBuff;
                    }
                }
            }
            if(RelevantBuffCount > 0)
            {
                Vector2 BuffIconStartLocation = ScreenLocation;
                if(NumArmorPieces > 0)
                {
                    BuffIconStartLocation.Y += IconSize;
                }
                float BuffsWidth = IconSize * RelevantBuffCount;
                BuffIconStartLocation.X -= BuffsWidth/2;
                for(int i = 0; i<5; i++)
                {
                    if(ReleventBuffsFound[i])
                    {
                        UObject* Buff = ReleventBuffPointers[i];
                        string BuffName = gameUtils.SGetObjectName(Buff);
                        [BuffButtons[i] move:BuffIconStartLocation.X y:BuffIconStartLocation.Y];
                        [BuffButtons[i] setBackgroundImage:GetBuffImage(BuffName) forState:UIControlStateNormal];
                        BuffIconStartLocation.X += IconSize;
                    }
                }
            }
        }
    }
    
    UObject* PlayerWeapon = utils.Read<UObject*>(Player + 0x1828);
    if(utils.isValidAdress(PlayerWeapon) && ESPWeaponIcon)
    {
        string WeaponName = gameUtils.SGetObjectName(PlayerWeapon);
        if(isValidWeaponImage(WeaponName))
        {
            Vector2 WeaponImageStartLocation = ScreenLocation;
            //Move Icon up based off health bar height
            if(ESPHealthBar)
            {
                WeaponImageStartLocation.Y -= 15;
            }
            //Move Icon up based on name height
            if(ESPPlayerName || ESPTribeName)
            {
                string HeightString = "LVL";
                FString* FTribeName = (FString*)(Player + 0xad0);
                if(ESPTribeName && FTribeName->Count > 1)
                {
                    HeightString = HeightString + "\n LVL2";
                }
                const char *str = HeightString.c_str();
                ImVec2 textSize = ImGui::GetFont()->CalcTextSizeA(ESPSize, MAXFLOAT, 0.0f, str);
                WeaponImageStartLocation.Y -= textSize.y;
            }
            
            WeaponImageStartLocation.X -= IconSize * WeaponIconWidthMultiplier/2;
            WeaponImageStartLocation.Y -= IconSize * WeaponIconHeightMultiplier;
            
            [WeaponButton move:WeaponImageStartLocation.X y:WeaponImageStartLocation.Y];
            [WeaponButton setBackgroundImage:GetWeaponImage(WeaponName) forState:UIControlStateNormal];
        }
    }
}
